using System;
using RecompOne.Runtime.Events;
using RecompOne.Runtime.Modding;

// Companion of the zh-cn translation pack. Generated by sotn-zh/tools/make_mod.py; see there.
//  - area names: the popup draws the name from a 4bpp block at VRAM (64, 256), whole and then in
//    dissolving pieces, so the block itself is rewritten when it holds a US name;
//  - the title screen's "PRESS START BUTTON": three 16-row strips of a 4bpp sheet drawn end to end,
//    rewritten in place with the same palette indices (its gold gradient and green flash stay);
//  (the intro card and the prologue stage title are replacement textures of the translation pack)
//  - "Obtained " (pickups) in each stage overlay, rewritten once the overlay is in memory;
public class ZhCnMod : IMod
{
    private const bool DEBUG = false;

    // --- area names
    private const int PageX = 64, PageY = 256, Words = 29, Rows = 40;
    private static readonly (int u0, int v0)[] Halves = { (4, 0), (8, 64) };

    private sealed record Area(ulong Original, ushort[] Left, ushort[] Right);
    private static readonly Area[] Areas =
    {
        new(0xD29F074CD941DE77UL, Words16(""), Words16("")), // Alchemy Laboratory
        new(0x8F718F102B3FB658UL, Words16(""), Words16("")), // Marble Gallery
        new(0xF9E64EB5536F8930UL, Words16(""), Words16("")), // Outer Wall
        new(0x668FF4C19634311BUL, Words16(""), Words16("")), // Elevator activated
        new(0x7FB38124D3EEF895UL, Words16(""), Words16("")), // Long Library
        new(0x3561AB32298F5602UL, Words16(""), Words16("")), // Royal Chapel
        new(0x5E694FD05C9BD972UL, Words16(""), Words16("")), // Clock Tower
        new(0x59D9AC7292FDC995UL, Words16(""), Words16("")), // Castle Keep
        new(0x5316F7B719420D6FUL, Words16(""), Words16("")), // Olrox's Quarters
        new(0xBD3769B7AB3461F0UL, Words16(""), Words16("")), // Colosseum
        new(0x4793BA72ED55A400UL, Words16(""), Words16("")), // Underground Caverns
        new(0x18F671061FDFAB49UL, Words16(""), Words16("")), // Abandoned Mine
        new(0xADA0CAB32B74A81CUL, Words16(""), Words16("")), // Catacombs
        new(0xF3D5019F152D2722UL, Words16(""), Words16("")), // Nightmare
    };

    // --- title screen "PRESS START BUTTON" (texpage 24, u 128..255, v 176..223)
    private const int PressX = 544, PressY = 432, PressWords = 32, PressRows = 48;
    private const ulong PressUs = 0x0ADF70DE511BD790UL;
    private static readonly ushort[] PressZh = Words16("");

    // --- "Obtained "
    private static readonly uint[] Obtained = { 0x80186F48u, 0x80188D68u, 0x8018AB50u, 0x8018D578u, 0x80190FDCu, 0x801919DCu, 0x80191F34u, 0x80192F18u, 0x80193578u, 0x80193758u, 0x801950E4u, 0x801974DCu, 0x8019902Cu, 0x8019A224u, 0x8019AF5Cu, 0x8019B234u, 0x8019CBC4u, 0x8019D02Cu, 0x8019FA08u, 0x8019FD2Cu, 0x801A07B4u, 0x801A0C38u, 0x801A20F8u, 0x801A5360u, 0x801A5AB0u, 0x801A5D04u, 0x801A6168u, 0x801A6470u, 0x801A8B04u, 0x801A9788u, 0x801AACA4u, 0x801ADA64u, 0x801AF750u, 0x801B003Cu, 0x801B07C8u, 0x801B1158u, 0x801B1D9Cu, 0x801B1FA0u, 0x801B2D0Cu, 0x801B2F7Cu, 0x801B4248u, 0x801B4930u, 0x801B53B8u, 0x801B5BA0u, 0x801B6908u, 0x801B7618u, 0x801C0080u, 0x801C0BA4u, 0x801C141Cu, 0x801C458Cu };
    private static readonly byte[] ObtainedUs = System.Text.Encoding.ASCII.GetBytes("Obtained ");
    private static readonly byte[] ObtainedZh = { 0x93, 0xBE, 0x93, 0x9E, 0x20, 0x00 };

    public void OnLoad() => Event.AddListener<VSyncEvent>(OnVSync);
    public void OnUnload() => Event.RemoveListener<VSyncEvent>(OnVSync);

    private static void OnVSync(VSyncEvent e)
    {
        PatchObtained();
        var gpu = RecompOne.Runtime.Runtime.Gpu;
        if (gpu == null) return;
        ReplaceAreaName(gpu);
        ReplacePress(gpu);
    }

    private static void Log(string s)
    {
        if (!DEBUG) return;
        try { System.IO.File.AppendAllText("zh-cn-debug.log", $"{DateTime.Now:HH:mm:ss.fff} {s}\n"); } catch { }
    }

    private static ushort[] Words16(string b64)
    {
        var bytes = Convert.FromBase64String(b64);
        var w = new ushort[bytes.Length / 2];
        Buffer.BlockCopy(bytes, 0, w, 0, bytes.Length);
        return w;
    }

    private static void PatchObtained()
    {
        var m = RecompOne.Runtime.Runtime.Mem;
        if (m == null) return;
        foreach (uint a in Obtained)
        {
            bool match = true;
            for (int i = 0; i < ObtainedUs.Length && match; i++) match = m.ReadU8(a + (uint)i) == ObtainedUs[i];
            if (!match) continue;
            for (int i = 0; i < ObtainedZh.Length; i++) m.WriteU8(a + (uint)i, ObtainedZh[i]);
        }
    }

    private static void ReplaceAreaName(RecompOne.Runtime.Gpu gpu)
    {
        var vram = gpu.Vram;
        ulong h = 1469598103934665603UL;
        int x0 = PageX + (Halves[0].u0 >> 2);
        for (int y = 0; y < Rows; y++)
        {
            int row = (PageY + Halves[0].v0 + y) * 1024 + x0;
            for (int i = 0; i < Words; i++)
            {
                ushort v = vram[row + i];
                h = (h ^ (byte)v) * 1099511628211UL;
                h = (h ^ (byte)(v >> 8)) * 1099511628211UL;
            }
        }
        foreach (var a in Areas)
        {
            if (a.Original != h) continue;
            Upload(gpu, PageX + (Halves[0].u0 >> 2), PageY + Halves[0].v0, Words, Rows, a.Left);
            Upload(gpu, PageX + (Halves[1].u0 >> 2), PageY + Halves[1].v0, Words, Rows, a.Right);
            Log("area name replaced");
            return;
        }
    }

    private static void ReplacePress(RecompOne.Runtime.Gpu gpu)
    {
        var vram = gpu.Vram;
        ulong h = 1469598103934665603UL;
        for (int y = 0; y < PressRows; y++)
            for (int i = 0; i < PressWords; i++)
            {
                ushort v = vram[(PressY + y) * 1024 + PressX + i];
                h = (h ^ (byte)v) * 1099511628211UL;
                h = (h ^ (byte)(v >> 8)) * 1099511628211UL;
            }
        if (h != PressUs) return;
        Upload(gpu, PressX, PressY, PressWords, PressRows, PressZh);
        Log("press start replaced");
    }

    // GP0 0xA0: CPU-to-VRAM copy of w x h halfwords at (x, y)
    private static void Upload(RecompOne.Runtime.Gpu gpu, int x, int y, int w, int h, ushort[] data)
    {
        gpu.WriteGp0(0xA0000000u);
        gpu.WriteGp0((uint)(y << 16 | x));
        gpu.WriteGp0((uint)(h << 16 | w));
        for (int i = 0; i < data.Length; i += 2)
            gpu.WriteGp0((uint)(data[i] | (i + 1 < data.Length ? data[i + 1] << 16 : 0)));
    }
}
